-- 4. Product images. The paths are root-relative assets the app itself ships,
--    not storage objects — resolveImageUrl() passes a leading-slash path
--    through untouched. Cleared first so a re-run cannot stack duplicates:
--    product_images has no unique key to conflict on.
delete from public.product_images i
 using public.products p
 where p.id = i.product_id
   and p.slug in ('clear-cup-16oz','pet-cup-22oz','hot-cup-8oz',
                 'black-flat-lid-95mm','dome-lid-95mm','cup-carrier-4',
                 'kraft-noodle-box','bagasse-clamshell-9in','pp-microwave-bowl-750',
                 'rice-tray-2-compartment','soup-cup-16oz','sauce-cup-2oz',
                 'kraft-bag-small','kraft-bag-medium','kraft-bag-large',
                 'greaseproof-snack-bag','bakery-window-bag','delivery-flat-bag',
                 'thermal-label-50x30','thermal-label-40x25','blank-sticker-roll-40mm',
                 'fragile-sticker-roll','date-label-pack','receipt-roll-58mm',
                 'stainless-bar-spoon','ice-scoop-stainless','cocktail-shaker',
                 'milk-pitcher-600ml','syrup-pump-pack','muddler-wood',
                 'bagasse-plate-9in','kraft-soup-bowl-500','compostable-straw',
                 'wooden-stirrer','bioplastic-cutlery-set','paper-lunch-box-eco');

