  ('date-label-pack', '/images/supplymate/products/date-label-pack.svg', 'สติกเกอร์ระบุวันผลิตแบบเขียน'),
  ('receipt-roll-58mm', '/images/supplymate/products/receipt-roll-58mm.svg', 'กระดาษใบเสร็จ 58 มม.'),
  ('stainless-bar-spoon', '/images/supplymate/products/stainless-bar-spoon.svg', 'ช้อนบาร์สเตนเลสด้ามเกลียว'),
  ('ice-scoop-stainless', '/images/supplymate/products/ice-scoop-stainless.svg', 'ที่ตักน้ำแข็งสเตนเลส'),
  ('cocktail-shaker', '/images/supplymate/products/cocktail-shaker.svg', 'เชคเกอร์สเตนเลส'),
  ('milk-pitcher-600ml', '/images/supplymate/products/milk-pitcher-600ml.svg', 'เหยือกตีฟองนม 600 มล.'),
  ('syrup-pump-pack', '/images/supplymate/products/syrup-pump-pack.svg', 'หัวปั๊มไซรัปมาตรฐาน'),
  ('muddler-wood', '/images/supplymate/products/muddler-wood.svg', 'ไม้บดสมุนไพรด้ามไม้'),
  ('bagasse-plate-9in', '/images/supplymate/products/bagasse-plate-9in.svg', 'จานชานอ้อย 9 นิ้ว'),
  ('kraft-soup-bowl-500', '/images/supplymate/products/kraft-soup-bowl-500.svg', 'ชามกระดาษคราฟท์ 500 มล.'),
  ('compostable-straw', '/images/supplymate/products/compostable-straw.svg', 'หลอดย่อยสลายได้'),
  ('wooden-stirrer', '/images/supplymate/products/wooden-stirrer.svg', 'ไม้คนกาแฟ'),
  ('bioplastic-cutlery-set', '/images/supplymate/products/bioplastic-cutlery-set.svg', 'ชุดช้อนส้อมไบโอพลาสติก'),
  ('paper-lunch-box-eco', '/images/supplymate/products/paper-lunch-box-eco.svg', 'กล่องกระดาษคราฟท์รักษ์โลก 1 ช่อง')
) as v(slug, storage_path, alt)
join public.products p on p.slug = v.slug;

-- 5. Price ladders. Percentages rather than fixed amounts so every product's
--    ladder stays sensible against its own base price. The last product in
--    each category is left without one on purpose: a catalogue where
--    everything has tiers hides what the "มีราคาขั้นบันได" filter and the
--    "ยังไม่มีขั้น" admin badge are actually for.
delete from public.product_price_tiers t
 using public.products p
 where p.id = t.product_id;

insert into public.product_price_tiers (product_id, min_quantity, unit_price)
select p.id, s.min_qty, round(p.price * s.factor, 2)
from public.products p
join (values
  (5, 0.96), (10, 0.93), (20, 0.90), (50, 0.86), (100, 0.82)
) as s(min_qty, factor) on true
where p.slug in ('clear-cup-16oz','pet-cup-22oz','hot-cup-8oz',
                 'black-flat-lid-95mm','dome-lid-95mm','kraft-noodle-box',
                 'bagasse-clamshell-9in','pp-microwave-bowl-750','rice-tray-2-compartment',
                 'soup-cup-16oz','kraft-bag-small','kraft-bag-medium',
                 'kraft-bag-large','greaseproof-snack-bag','bakery-window-bag',
                 'date-label-pack','stainless-bar-spoon','ice-scoop-stainless',
                 'cocktail-shaker','milk-pitcher-600ml','syrup-pump-pack',
                 'bagasse-plate-9in','kraft-soup-bowl-500','compostable-straw',
                 'wooden-stirrer','bioplastic-cutlery-set')
  and s.min_qty > p.min_order_quantity;

-- The higher-MOQ items get a ladder that starts above their own minimum,
-- because a tier at or below it is unreachable and the trigger rejects it.
insert into public.product_price_tiers (product_id, min_quantity, unit_price)
select p.id, s.min_qty, round(p.price * s.factor, 2)
from public.products p
join (values
  (12, 0.95), (24, 0.91), (60, 0.87), (120, 0.83)
) as s(min_qty, factor) on true
where p.slug in ('thermal-label-50x30','thermal-label-40x25','blank-sticker-roll-40mm',
                 'fragile-sticker-roll')
  and s.min_qty > p.min_order_quantity;

commit;

-- What the storefront should look like afterwards.
select p.name,
       p.package_unit || ' · ' || p.units_per_package || ' ชิ้น' as pack,
       p.price,
       p.price_per_piece,
       count(distinct t.id) as tiers,
       count(distinct i.id) as images
  from public.products p
  left join public.product_price_tiers t on t.product_id = p.id
  left join public.product_images i on i.product_id = p.id
 where p.status = 'active'
 group by p.id, p.name, p.package_unit, p.units_per_package, p.price, p.price_per_piece, p.sort_order
 order by p.sort_order;
